window.AUTH=window.AUTH||{};window.AUTH["21-432"]={"d":"21-432","id":"2022/21-432","n":"Arellano v. McDonough","briefs":[{"k":"petitioner","label":"Brief of petitioner Adolfo R. Arellano","date":"2022-05-13","url":"https://www.supremecourt.gov/DocketPDF/21/21-432/225337/20220513135416039_Arellano%20SCOTUS%20Opening%20Brief%20051322.pdf","side":"pet","n":78},{"k":"respondent","label":"Brief of respondent McDonough, Denis, Secretary of Veterans Affairs","date":"2022-07-18","url":"https://www.supremecourt.gov/DocketPDF/21/21-432/230302/20220718173458614_21-432bsUnitedStates.pdf","side":"res","n":84},{"k":"reply","label":"Reply of petitioner Adolfo R. Arellano","date":"2022-08-17","url":"https://www.supremecourt.gov/DocketPDF/21/21-432/233802/20220817145538938_Arellano%20Merits%20Reply%20Brief.pdf","side":"pet","n":48}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/598us1r1_3e04.pdf","tr":true,"items":[{"t":"case","label":"Andrews v. Orr","cite":"851 F.2d 146","y":1988,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/851/146/","by":{"0":"42"}},{"t":"case","label":"Andrews v. Principi","cite":"351 F.3d 1134","y":2003,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/351/1134/","by":{"0":"1, 39, 45","1":"5, 36"}},{"t":"case","label":"Attipoe v. Barr","cite":"945 F.3d 76","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/945/76/","by":{"0":"42"}},{"t":"case","label":"Bailey v. West","cite":"160 F.3d 1360","y":1998,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/160/1360/","by":{"0":"34"},"q":[{"src":"brief","b":0,"text":"a special class of citizens, those who risked harm to serve and - 34 - defend their country,","cite":"160 F.3d 1360, 1370"}]},{"t":"case","label":"Boone v. Lightner","cite":"319 U.S. 561","y":1943,"id":"scdb/1942-138","sc":1,"by":{"0":"27","2":"25"},"q":[{"src":"brief","b":0,"text":"those who have been obliged to drop their own affairs to take up the burdens of the nation.","cite":"319 U.S. 561, 575"},{"src":"brief","b":2,"text":"those who have been obliged to drop their own affairs to take up the burdens of the nation.","cite":"319 U.S. 561, 575"}]},{"t":"case","label":"Brown v. Gardner","cite":"513 U.S. 115","y":1994,"id":"1994/93-1128","sc":1,"by":{"0":"28","1":"42"}},{"t":"case","label":"Butler v. Peake","cite":"2008 WL 5101007","y":2008,"court":"Vet. App. Nov. 26","by":{"0":"44, 45"}},{"t":"case","label":"Butler v. Shinseki","cite":"603 F.3d 922","y":2010,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/603/922/","by":{"0":"38","1":"36"}},{"t":"case","label":"- viii - Chapman v. Choicecare Long Island Long Term Disability Income Plan","cite":"2004 U.S. Dist. LEXIS 26546","y":2004,"court":"E.D.N.Y. May 28","by":{"0":"41"}},{"t":"case","label":"CTS Corp. v. Waldburger","cite":"573 U.S. 1","y":2014,"id":"2013/13-339","sc":1,"by":{"0":"20, 24"},"q":[{"src":"brief","b":0,"text":"plaintiffs to - 20 - pursue ‘diligent prosecution of known claims,’","cite":"573 U.S. 1, 8"}]},{"t":"case","label":"DeBrunner v. Midway Equip. Co.","cite":"803 F.2d 950","y":1986,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/803/950/","by":{"0":"18"}},{"t":"case","label":"eBay Inc. v. MercExchange, L.L.C.","cite":"547 U.S. 388","y":2006,"id":"2005/05-130","sc":1,"by":{"0":"24"}},{"t":"case","label":"Fishgold v. Sullivan Drydock & Repair Corp.","cite":"328 U.S. 275","y":1946,"id":"scdb/1945-102","sc":1,"by":{"0":"28"},"q":[{"src":"brief","b":0,"text":"liberally construed for the benefit of those who left private life to serve their country in its hour of great need.","cite":"328 U.S. 275, 285"}]},{"t":"case","label":"Ford v. McDonald","cite":"2016 WL 4137532","y":2016,"court":"Vet. App. Aug. 3","by":{"0":"43"}},{"t":"case","label":"Former Emps. of Fisher & Co. v. U.S. Dep’t of Lab.","cite":"31 C.I.T. 1272","y":2007,"url":"https://www.courtlistener.com/c/C.I.T./31/1272/","by":{"0":"41"}},{"t":"case","label":"Goonsuwan v. Ashcroft","cite":"252 F.3d 383","y":2001,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/252/383/","by":{"0":"51"}},{"t":"case","label":"Hallstrom v. Tillamook County","cite":"493 U.S. 20","y":1989,"id":"1989/88-42","sc":1,"by":{"0":"18, 19, 26","1":"15, 16, 25","2":"4, 25"},"q":[{"src":"brief","b":1,"text":"triggered by the violation giving rise to the action,","cite":"493 U.S. at 27"}]},{"t":"case","label":"Hardaway v. Hartford Pub. Works Dep’t","cite":"879 F.3d 486","y":2018,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/879/486/","by":{"0":"16","2":"4"}},{"t":"case","label":"- ix - Harrison v. PPG Indus., Inc.","cite":"446 U.S. 578","y":1980,"id":"1979/78-1918","sc":1,"by":{"0":"39"}},{"t":"case","label":"Henderson ex. rel. Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"by":{"0":"passim","1":"19, 26, 33, 41","2":"7"},"q":[{"src":"brief","b":0,"text":"Time and again, we have described filing deadlines as ‘quintessential claim-processing rules,’ which ‘seek to promote the orderly progress of litigation,’ but do not deprive a court of authority to hear a case.","cite":"562 U.S. 428, 435"},{"src":"brief","b":0,"text":"VA must give the veteran the benefit of any doubt.","cite":"562 U.S. at 440"},{"src":"brief","b":1,"text":"faces no time limit for filing a claim.","cite":"562 U.S. 428, 431"},{"src":"brief","b":1,"text":"provisions for benefits to members of the Armed Services are to be construed in the beneficiaries’ favor.","cite":"562 U.S. at 441"}]},{"t":"case","label":"INS v. Orlando Ventura","cite":"537 U.S. 12","y":2002,"id":"2002/02-29","sc":1,"by":{"0":"50-51"}},{"t":"case","label":"Irwin v. Dep’t of Veterans Affairs","cite":"498 U.S. 89","y":1990,"id":"1990/89-5867","sc":1,"by":{"0":"passim","1":"passim","2":"passim"},"q":[{"src":"brief","b":0,"text":"‘a garden variety claim of excusable neglect,’ to which equitable tolling does not apply","cite":"498 U.S. at 96"},{"src":"brief","b":1,"text":"the caveat that ‘Congress, of course, may provide otherwise if it wishes to do so.’","cite":"498 U.S. at 96"},{"src":"brief","b":1,"text":"is likely to be a realistic assessment of legislative intent.","cite":"498 U.S. at 95"},{"src":"argument","who":"Mr. Barney","text":"The Irwin presumption in favor of -- of equitable tolling applies to this one-year deadline because it's a non-jurisdictional claims-processing rule set forth in a statute for which Congress has waived sovereign immunity."},{"src":"argument","who":"Justice Jackson","text":"Counsel, I have a question because you have set this up as whether or not we have a statute of limitations here, because you're trying to take advantage of Irwin and equal -- equitable tolling."},{"src":"argument","who":"Mr. Barney","text":"I think that's the point of Irwin, is that when Congress passes non-jurisdictional claims-processing deadlines of the sort we have here, that those deadlines by -- merely by the silence of Congress, by saying nothing, that those deadlines are presumed to come prepackaged with equitable power to toll the deadline for good cause."}]},{"t":"case","label":"Jaquay v. Principi","cite":"304 F.3d 1276","y":2002,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/304/1276/","by":{"0":"28"}},{"t":"case","label":"John R. Sand & Gravel Co. v. United States","cite":"552 U.S. 130","y":2008,"id":"2007/06-1164","sc":1,"by":{"0":"20","1":"15","2":"6, 15"},"q":[{"src":"brief","b":0,"text":"protect defendants against stale or unduly delayed claims,","cite":"552 U.S. 130, 133"}]},{"t":"case","label":"Johnson v. Robison","cite":"415 U.S. 361","y":1974,"id":"1973/72-1297","sc":1,"by":{"0":"27"},"q":[{"src":"brief","b":0,"text":"the economic and family detriments which are peculiar to military service.","cite":"415 U.S. 361, 380"}]},{"t":"case","label":"K. G. v. Sec’y of Health & Hum. Servs.","cite":"951 F.3d 1374","y":2020,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/951/1374/","by":{"0":"49"},"q":[{"src":"brief","b":0,"text":"there is no claim that Mr. Arellano was estranged from Mr. Lamar or refused to interact with him,","cite":"951 F.3d at 1377"}]},{"t":"case","label":"Kappen v. Wilkie","cite":"2019 WL 3949462","y":2019,"court":"Vet. App. Aug. 22","by":{"0":"43"}},{"t":"case","label":"Lozano v. Montoya Alvarez","cite":"572 U.S. 1","y":2014,"id":"2013/12-820","sc":1,"by":{"0":"20, 25","1":"passim","2":"passim"},"q":[{"src":"brief","b":1,"text":"Congress ‘legislates against a background of commonlaw adjudicatory principles.’","cite":"572 U.S. 1, 10"},{"src":"brief","b":1,"text":"only applied [the] presumption [of equitable tolling] to statutes of limitations.","cite":"572 U.S. at 13"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"effectively extends an otherwise discrete limitations period set by Congress.","cite":"572 U. S. 1, 10"},{"src":"argument","who":"Mr. Joshi","text":"And I think Lozano later said statutory intent. But -- but the point is equitable tolling is authorized only because we read text that looks like a limitations period as an implicit grant of authority to the judiciary to toll that particular deadline."},{"src":"argument","who":"Justice Kagan","text":"You know, it seems like Lozano says very clearly that we're supposed to consider this question of what a statute of limitations is in a functional way, not in a formal way."},{"src":"argument","who":"Mr. Joshi","text":"I think the functional characteristics are certainly a necessary feature to trigger the -- the Irwin presumption, as Lozano makes clear, but I also think there's a secondary feature which -- which was essentially or in part at least the motivation of Lozano's alternative holding, which was that, look, this is a treaty and, of course, treaty-makers don't draft against the back -- backdrop of this common law rule."}]},{"t":"case","label":"Messa v. Goord","cite":"652 F.3d 305","y":2011,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/652/305/","by":{"0":"16","2":"4"}},{"t":"case","label":"Nutraceutical Corp. v. Lambert","cite":"139 S. Ct. 710","y":2019,"id":"2018/17-1094","sc":1,"by":{"0":"30","1":"26, 29, 41"},"q":[{"src":"brief","b":1,"text":"Whether a rule precludes equitable tolling turns not on its jurisdictional character but rather on whether the text of the rule leaves room for such flexibility.","cite":"139 S. Ct. at 714"}]},{"t":"case","label":"Petrella v. Metro-Goldwyn-Mayer, Inc.","cite":"572 U.S. 663","y":2014,"id":"2013/12-1315","sc":1,"by":{"0":"22, 23","1":"18, 25","2":"10"},"q":[{"src":"brief","b":0,"text":"single benefits claim for an ongoing disability.","cite":"572 U.S. at 671"}]},{"t":"case","label":"Pullman-Standard v. Swint","cite":"456 U.S. 273","y":1982,"id":"1981/80-1190","sc":1,"by":{"0":"51"}},{"t":"case","label":"Raybine v. Wilkie","cite":"31 Vet. App. 419","y":2019,"url":"https://www.courtlistener.com/c/Vet.%20App./31/419/","by":{"0":"3"}},{"t":"case","label":"Rhoa-Zamora v. INS","cite":"971 F.2d 26","y":1992,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/971/26/","by":{"0":"51"}},{"t":"case","label":"Rotella v. Wood","cite":"528 U.S. 549","y":2000,"id":"1999/98-896","sc":1,"by":{"0":"20, 21"},"q":[{"src":"brief","b":0,"text":"basic policies [furthered by] all limitations provisions: repose, elimination of stale claims, and certainty about a plaintiff’s opportunity for recovery and a defendant’s potential liabilities.","cite":"528 U.S. 549, 555"},{"src":"brief","b":0,"text":"basic policies of . . . repose, elimination of stale claims, and certainty about a plaintiff’s opportunity for recovery and a defendant’s potential liabilities.","cite":"528 U.S. at 555"}]},{"t":"case","label":"Savage v. Wilkie","cite":"2020 WL 1846012","y":2020,"court":"Vet. App. Apr. 13","by":{"0":"43, 44"}},{"t":"case","label":"SCA Hygiene Prods. Aktiebolag v. First Quality Baby Prods., LLC","cite":"137 S. Ct. 954","y":2017,"id":"2016/15-927","sc":1,"by":{"0":"23","1":"25","2":"10"}},{"t":"case","label":"Scarborough v. Principi","cite":"541 U.S. 401","y":2004,"id":"2003/02-1657","sc":1,"by":{"0":"passim","1":"17, 18, 20","2":"5, 9, 19"}},{"t":"case","label":"Sebelius v. Auburn Reg’l Med. Ctr.","cite":"568 U.S. 145","y":2013,"id":"2012/11-1231","sc":1,"by":{"0":"14, 29, 38","1":"16, 36","2":"19"},"q":[{"src":"brief","b":0,"text":"one ‘in which laymen, unassisted by trained lawyers, initiate the - 29 - process.’","cite":"568 U.S. at 159"}]},{"t":"case","label":"- xi - SEC v. Chenery Corp.","cite":"332 U.S. 194","y":1947,"id":"scdb/1946-133","sc":1,"by":{"0":"50"}},{"t":"case","label":"Shinseki v. Sanders","cite":"556 U.S. 396","y":2009,"id":"2008/07-1209","sc":1,"by":{"0":"27","1":"42"},"q":[{"src":"brief","b":0,"text":"A veteran, after all, has performed an especially important service for the Nation, often at the risk of his or her own life.","cite":"556 U.S. 396, 412"},{"src":"brief","b":0,"text":"VA has a statutory duty to help the veteran develop his or her benefits claim.","cite":"556 U.S. at 412"}]},{"t":"case","label":"Small v. Camden County","cite":"728 F.3d 265","y":2013,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/728/265/","by":{"0":"16"}},{"t":"case","label":"Taylor v. McDonough","cite":"3 F.4th 1351","y":2021,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.4th/3/1351/","by":{"0":"45, 46"}},{"t":"case","label":"Taylor v. McDonough","cite":"4 F.4th 1381","y":2021,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.4th/4/1381/","by":{"0":"45, 46"}},{"t":"case","label":"Taylor v. Wilkie","cite":"31 Vet. App. 147","y":2019,"url":"https://www.courtlistener.com/c/Vet.%20App./31/147/","by":{"0":"46"}},{"t":"case","label":"Tejeda-Mata v. INS","cite":"626 F.2d 721","y":1980,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/626/721/","by":{"0":"51"}},{"t":"case","label":"Torello v. UNUM Life Ins. Co. of Am.","cite":"1999 U.S. App. LEXIS 32228","y":1999,"court":"6th Cir. Dec. 3","by":{"0":"41-42"}},{"t":"case","label":"Truitt v. County of Wayne","cite":"148 F.3d 644","y":1998,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/148/644/","by":{"0":"18"}},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"by":{"0":"29, 36, 37","1":"30","2":"13, 14, 20, 23"}},{"t":"case","label":"- xii - Uanreroro v. Gonzales","cite":"443 F.3d 1197","y":2006,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/443/1197/","by":{"0":"51"}},{"t":"case","label":"United States v. Beggerly","cite":"524 U.S. 38","y":1998,"id":"1997/97-731","sc":1,"by":{"0":"29, 35","1":"26, 27, 28, 31, 37","2":"13, 14"}},{"t":"case","label":"United States v. Brockamp","cite":"519 U.S. 347","y":1997,"id":"1996/95-1225","sc":1,"by":{"0":"passim","1":"passim","2":"17, 18, 21, 22"},"q":[{"src":"brief","b":0,"text":"Irwin’s negatively phrased question: Is there good reason to believe that Congress did not want the equitable tolling doctrine to apply","cite":"519 U.S. 347, 350"},{"src":"brief","b":0,"text":"sets forth its limitations in a highly detailed technical manner.","cite":"519 U.S. at 350"},{"src":"brief","b":2,"text":"can often plausibly [be] read as containing an implied ‘equitable tolling’ exception.","cite":"519 U.S. at 350"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"there [is] good reason to believe that Congress did not want the equitable tolling doctrine to apply.","cite":"519 U. S. 347, 350"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"nature of the underlying subject matter—tax collection—underscore[d] the linguistic point.","cite":"519 U. S., at 352"},{"src":"argument","who":"Mr. Joshi","text":"I don't think it's provided for by the statute under the normal rules of Irwin and Brockamp, and because of that, I think, fundamentally, it's -- it's going to be a question for -- for Congress."},{"src":"argument","who":"Mr. Joshi","text":"And, indeed, in Brockamp, that's exactly the approach this Court took. The Court said, we assume for argument's sake that this is tollable and that the Irwin presumption applies, but in this case, all the statutory indicia have rebutted that presumption, and we think that would actually be a perfectly sound way to proceed in this case because, however strong our arguments are on the inapplicability of the presumption, I think they're even stronger and more clear that any such presumption would have been rebutted in -- in this case."},{"src":"argument","who":"Mr. Joshi","text":"So I -- I disagree, Mr. Chief Justice. That's certainly not how this Court has framed it in cases like Brockamp and --"}]},{"t":"case","label":"United States v. Kwai Fun Wong","cite":"575 U.S. 402","y":2015,"id":"2014/13-1074","sc":1,"by":{"0":"passim","1":"41","2":"16"},"q":[{"src":"brief","b":0,"text":"A rebuttable presumption, of course, may be rebutted, so Irwin does not end the matter.","cite":"575 U.S. at 408"},{"src":"brief","b":0,"text":"is to show that Congress made the time bar at issue jurisdictional.","cite":"575 U.S. at 408"},{"src":"argument","who":"Mr. Barney","text":"Most statutes of limitations are written with words of emphasis, things like shall be forever barred, and as this Court found in Kwai Fun Wong, that's of no moment to whether or not equitable tolling can apply to that statute of limitations."},{"src":"argument","who":"Mr. Barney","text":"Zipes is an example of that, and also the companion case to Kwai Fun Wong, which was in June, had to do with the -- with the filing deadline at the agency level."}]},{"t":"case","label":"United States v. Oregon","cite":"366 U.S. 643","y":1961,"id":"1960/329","sc":1,"by":{"0":"27"},"q":[{"src":"brief","b":0,"text":"The solicitude of Congress for veterans is of long standing.","cite":"366 U.S. 643, 647"}]},{"t":"case","label":"Walters v. Nat’l Ass’n of Radiation Survivors","cite":"473 U.S. 305","y":1985,"id":"1984/84-571","sc":1,"by":{"0":"27, 40","1":"2, 19, 21, 26"},"q":[{"src":"brief","b":0,"text":"is designed to function throughout with a high degree of informality and solicitude for the claimant.","cite":"473 U.S. 305, 311"},{"src":"brief","b":0,"text":"designed to function throughout with a high degree of informality and solicitude for the claimant.","cite":"473 U.S. at 311"},{"src":"brief","b":1,"text":"causally related to an injury sustained in the service.","cite":"473 U.S. 305, 307"}]},{"t":"case","label":"Winchester v. Off. of Pers. Mgmt.","cite":"449 F. App’x 936","y":2011,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/449/936/","by":{"0":"40, 41"}},{"t":"case","label":"Wright v. Gober","cite":"10 Vet. App. 343","y":1997,"url":"https://www.courtlistener.com/c/Vet.%20App./10/343/","by":{"0":"22","2":"6"}},{"t":"case","label":"Young v. United States","cite":"535 U.S. 43","y":2002,"id":"2001/00-1567","sc":1,"by":{"0":"passim","1":"16, 23, 24, 25","2":"passim"},"q":[{"src":"brief","b":0,"text":"limited statute of limitations, but a statute of limitations nonetheless.","cite":"535 U.S. at 47"},{"src":"brief","b":1,"text":"limitations periods are ‘customarily subject to equitable tolling,’","cite":"535 U.S. at 49"}]},{"t":"case","label":"Zipes v. Trans World Airlines, Inc.","cite":"455 U.S. 385","y":1982,"id":"1981/78-1545","sc":1,"by":{"0":"15, 16, 27","1":"17, 20","2":"3, 4, 5"},"q":[{"src":"argument","who":"Mr. Barney","text":"Zipes is an example of that, and also the companion case to Kwai Fun Wong, which was in June, had to do with the -- with the filing deadline at the agency level."}]},{"t":"usc","label":"5 U.S.C. § 8337","url":"https://www.law.cornell.edu/uscode/text/5/8337","subs":["(b)"],"by":{"0":"40"}},{"t":"usc","label":"11 U.S.C. § 507","url":"https://www.law.cornell.edu/uscode/text/11/507","subs":["(a)(8)(A)(i)","(a)(1)(A)"],"stext":{"head":"§507. Priorities","paras":[[0,"(a) The following expenses and claims have priority in the following order:"],[1,"(1) First:"],[2,"(A) Allowed unsecured claims for domestic support obligations that, as of the date of the filing of the petition in a case under this title, are owed to or recoverable by a spouse, former spouse, or child of the debtor, or such child's parent, legal guardian, or responsible relative, without regard to whether the claim is filed by such person or is filed by a governmental unit on behalf of such person, on the condition that funds received under this paragraph by a governmental unit under this title after the date of the filing of the petition shall be applied and distributed in accordance with applicable nonbankruptcy law."],[2,"(B) Subject to claims under subparagraph (A), allowed unsecured claims for domestic support obligations that, as of the date of the filing of the petition, are assigned by a spouse, former spouse, child of the debtor, or such child's parent, legal guardian, or responsible relative to a governmental unit (unless such obligation is assigned voluntarily by the spouse, former spouse, child, parent, legal guardian, or responsible relative of the child for the purpose of collecting the debt) or are owed directly to or recoverable by a governmental unit under applicable nonbankruptcy law, on the condition that funds received under this paragraph by a governmental unit under this title after the date of the filing of the petition be applied and distributed in accordance with applicable nonbankruptcy law."],[2,"(C) If a trustee is appointed or elected under section 701, 702, 703, 1104, 1202, or 1302, the administrative expenses of the trustee allowed under paragraphs (1)(A), (2), and (6) of section 503(b) shall be paid before payment of claims under subparagraphs (A) and (B), to the extent that the trustee administers assets that are otherwise available for the payment of such claims."],[1,"(2) Second, administrative expenses allowed under section 503(b) of this title, unsecured claims of any Federal reserve bank related to loans made through programs or facilities authorized under section 13(3) of the Federal Reserve Act (12 U.S.C. 343),1 and any fees and charges assessed against the estate under chapter 123 of title 28."],[1,"(3) Third, unsecured claims allowed under section 502(f) of this title."],[1,"(4) Fourth, allowed unsecured claims, but only to the extent of $10,000 2 for each individual or corporation, as the case may be, earned within 180 days before the date of the filing of the petition or the date of the cessation of the debtor's business, whichever occurs first, for—"],[2,"(A) wages, salaries, or commissions, including vacation, severance, and sick leave pay earned by an individual; or"],[2,"(B) sales commissions earned by an individual or by a corporation with only 1 employee, acting as an independent contractor in the sale of goods or services for the debtor in the ordinary course of the debtor's business if, and only if, during the 12 months preceding that date, at least 75 percent of the amount that the individual or corporation earned by acting as an independent contractor in the sale of goods or services was earned from the debtor."],[1,"(5) Fifth, allowed unsecured claims for contributions to an employee benefit plan—"],[2,"(A) arising from services rendered within 180 days before the date of the filing of the petition or the date of the cessation of the debtor's business, whichever occurs first; but only"],[2,"(B) for each such plan, to the extent of—"],[3,"(i) the number of employees covered by each such plan multiplied by $10,000; 2 less"],[3,"(ii) the aggregate amount paid to such employees under paragraph (4) of this subsection, plus the aggregate amount paid by the estate on behalf of such employees to any other employee benefit plan."],[1,"(6) Sixth, allowed unsecured claims of persons—"],[2,"(A) engaged in the production or raising of grain, as defined in section 557(b) of this title, against a debtor who owns or operates a grain storage facility, as defined in section 557(b) of this title, for grain or the proceeds of grain, or"],[2,"(B) engaged as a United States fisherman against a debtor who has acquired fish or fish produce from a fisherman through a sale or conversion, and who is engaged in operating a fish produce storage or processing facility—"],[1,"but only to the extent of $4,000 2 for each such individual."],[1,"(7) Seventh, allowed unsecured claims of individuals, to the extent of $1,800 2 for each such individual, arising from the deposit, before the commencement of the case, of money in connection with the purchase, lease, or rental of property, or the purchase of services, for the personal, family, or household use of such individuals, that were not delivered or provided."],[1,"(8) Eighth, allowed unsecured claims of governmental units, only to the extent that such claims are for—"],[2,"(A) a tax on or measured by income or gross receipts for a taxable year ending on or before the date of the filing of the petition—"],[3,"(i) for which a return, if required, is last due, including extensions, after three years before the date of the filing of the petition;"],[3,"(ii) assessed within 240 days before the date of the filing of the petition, exclusive of—"],[4,"(I) any time during which an offer in compromise with respect to that tax was pending or in effect during that 240-day period, plus 30 days; and"],[4,"(II) any time during which a stay of proceedings against collections was in effect in a prior case under this title during that 240-day period, plus 90 days; or"],[3,"(iii) other than a tax of a kind specified in section 523(a)(1)(B) or 523(a)(1)(C) of this title, not assessed before, but assessable, under applicable law or by agreement, after, the commencement of the case;"],[2,"(B) a property tax incurred before the commencement of the case and last payable without penalty after one year before the date of the filing of the petition;"],[2,"(C) a tax required to be collected or withheld and for which the debtor is liable in whatever capacity;"],[2,"(D) an employment tax on a wage, salary, or commission of a kind specified in paragraph (4) of this subsection earned from the debtor before the date of the filing of the petition, whether or not actually paid before such date, for which a return is last due, under applicable law or under any extension, after three years before the date of the filing of the petition;"],[2,"(E) an excise tax on—"],[3,"(i) a transaction occurring before the date of the filing of the petition for which a return, if required, is last due, under applicable law or under any extension, after three years before the date of the filing of the petition; or"],[3,"(ii) if a return is not required, a transaction occurring during the three years immediately preceding the date of the filing of the petition;"],[2,"(F) a customs duty arising out of the importation of merchandise—"],[3,"(i) entered for consumption within one year before the date of the filing of the petition;"],[3,"(ii) covered by an entry liquidated or reliquidated within one year before the date of the filing of the petition; or"],[3,"(iii) entered for consumption within four years before the date of the filing of the petition but unliquidated on such date, if the Secretary of the Treasury certifies that failure to liquidate such entry was due to an investigation pending on such date into assessment of antidumping or countervailing duties or fraud, or if information needed for the proper appraisement or classification of such merchandise was not available to the appropriate customs officer before such date; or"],[2,"(G) a penalty related to a claim of a kind specified in this paragraph and in compensation for actual pecuniary loss."],[1,"An otherwise applicable time period specified in this paragraph shall be suspended for any period during which a governmental unit is prohibited under applicable nonbankruptcy law from collecting a tax as a result of a request by the debtor for a hearing and an appeal of any collection action taken or proposed against the debtor, plus 90 days; plus any time during which the stay of proceedings was in effect in a prior case under this title or during which collection was precluded by the existence of 1 or more confirmed plans under this title, plus 90 days."],[1,"(9) Ninth, allowed unsecured claims based upon any commitment by the debtor to a Federal depository institutions regulatory agency (or predecessor to such agency) to maintain the capital of an insured depository institution."],[1,"(10) Tenth, allowed claims for death or personal injury resulting from the operation of a motor vehicle or vessel if such operation was unlawful because the debtor was intoxicated from using alcohol, a drug, or another substance."],[0,"(b) If the trustee, under section 362, 363, or 364 of this title, provides adequate protection of the interest of a holder of a claim secured by a lien on property of the debtor and if, notwithstanding such protection, such creditor has a claim allowable under subsection (a)(2) of this section arising from the stay of action against such property under section 362 of this title, from the use, sale, or lease of such property under section 363 of this title, or from the granting of a lien under section 364(d) of this title, then such creditor's claim under such subsection shall have priority over every other claim allowable under such subsection."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/507?type=usc&year=mostrecent&link-type=html"},"by":{"0":"20","1":"23, 23","2":"3"}},{"t":"usc","label":"19 U.S.C. § 2273","url":"https://www.law.cornell.edu/uscode/text/19/2273","subs":["(b)(1)(2002)"],"by":{"0":"41"}},{"t":"usc","label":"26 U.S.C. § 6511","url":"https://www.law.cornell.edu/uscode/text/26/6511","by":{"0":"33","1":"27"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"4"}},{"t":"usc","label":"28 U.S.C. § 2401","url":"https://www.law.cornell.edu/uscode/text/28/2401","subs":["(b)"],"stext":{"head":"§2401. Time for commencing action against United States","paras":[[0,"(a) Except as provided by chapter 71 of title 41, every civil action commenced against the United States shall be barred unless the complaint is filed within six years after the right of action first accrues. The action of any person under legal disability or beyond the seas at the time the claim accrues may be commenced within three years after the disability ceases."],[0,"(b) A tort claim against the United States shall be forever barred unless it is presented in writing to the appropriate Federal agency within two years after such claim accrues or unless action is begun within six months after the date of mailing, by certified or registered mail, of notice of final denial of the claim by the agency to which it was presented."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2401?type=usc&year=mostrecent&link-type=html"},"by":{"0":"32","2":"16"},"q":[{"src":"brief","b":0,"text":"A tort claim against the United States shall be forever barred unless it is presented in writing to the appropriate Federal agency within two years after such claim accrues . . . .","cite":"28 U.S.C. § 2401(b)"}]},{"t":"usc","label":"28 U.S.C. § 2409a","url":"https://www.law.cornell.edu/uscode/text/28/2409a","subs":["(g)"],"by":{"0":"35","1":"27, 27"},"q":[{"src":"brief","b":0,"text":"plaintiff ‘knew or should have known of the claim of the United States.’","cite":"28 U.S.C. § 2409a(g)"}]},{"t":"usc","label":"38 U.S.C. § 1114","url":"https://www.law.cornell.edu/uscode/text/38/1114","stext":{"head":"§1114. Rates of wartime disability compensation","paras":[[0,"For the purposes of section 1110 of this title—"],[1,"(a) if and while the disability is rated 10 percent the monthly compensation shall be $123;"],[1,"(b) if and while the disability is rated 20 percent the monthly compensation shall be $243;"],[1,"(c) if and while the disability is rated 30 percent the monthly compensation shall be $376;"],[1,"(d) if and while the disability is rated 40 percent the monthly compensation shall be $541;"],[1,"(e) if and while the disability is rated 50 percent the monthly compensation shall be $770;"],[1,"(f) if and while the disability is rated 60 percent the monthly compensation shall be $974;"],[1,"(g) if and while the disability is rated 70 percent the monthly compensation shall be $1,228;"],[1,"(h) if and while the disability is rated 80 percent the monthly compensation shall be $1,427;"],[1,"(i) if and while the disability is rated 90 percent the monthly compensation shall be $1,604;"],[1,"(j) if and while the disability is rated as total the monthly compensation shall be $2,673;"],[1,"(k) if the veteran, as the result of service-connected disability, has suffered the anatomical loss or loss of use of one or more creative organs, or one foot, or one hand, or both buttocks, or blindness of one eye, having only light perception, has suffered complete organic aphonia with constant inability to communicate by speech, or deafness of both ears, having absence of air and bone conduction, or, in the case of a woman veteran, has suffered the anatomical loss of 25 percent or more of tissue from a single breast or both breasts in combination (including loss by mastectomy or partial mastectomy) or has received radiation treatment of breast tissue, the rate of compensation therefor shall be $96 per month for each such loss or loss of use independent of any other compensation provided in subsections (a) through (j) or subsection (s) of this section but in no event to exceed $3,327 per month; and in the event the veteran has suffered one or more of the disabilities heretofore specified in this subsection, in addition to the requirement for any of the rates specified in subsections (l) through (n) of this section, the rate of compensation shall be increased by $96 per month for each such loss or loss of use, but in no event to exceed $4,667 per month;"],[1,"(l) if the veteran, as the result of service-connected disability, has suffered the anatomical loss or loss of use of both feet, or of one hand and one foot, or is blind in both eyes, with 5/200 visual acuity or less, or is permanently bedridden or with such significant disabilities as to be in need of regular aid and attendance, the monthly compensation shall be $3,327;"],[1,"(m) if the veteran, as the result of service-connected disability, has suffered the anatomical loss or loss of use of both hands, or of both legs with factors preventing natural knee action with prostheses in place, or of one arm and one leg with factors preventing natural elbow and knee action with prostheses in place, or has suffered blindness in both eyes having only light perception, or has suffered blindness in both eyes, rendering such veteran so significantly disabled as to be in need of regular aid and attendance, the monthly compensation shall be $3,671;"],[1,"(n) if the veteran, as the result of service-connected disability, has suffered the anatomical loss or loss of use of both arms with factors preventing natural elbow action with prostheses in place, has suffered the anatomical loss of both legs with factors that prevent the use of prosthetic appliances, or has suffered the anatomical loss of one arm and one leg with factors that prevent the use of prosthetic appliances, or has suffered the anatomical loss of both eyes, or has suffered blindness without light perception in both eyes, the monthly compensation shall be $4,176;"],[1,"(o) if the veteran, as the result of service-connected disability, has suffered disability under conditions which would entitle such veteran to two or more of the rates provided in one or more subsections (l) through (n) of this section, no condition being considered twice in the determination, or if the veteran has suffered bilateral deafness (and the hearing impairment in either one or both ears is service connected) rated at 60 percent or more disabling and the veteran has also suffered service-connected total blindness with 20/200 visual acuity or less, or if the veteran has suffered service-connected total deafness in one ear or bilateral deafness (and the hearing impairment in either one or both ears is service connected) rated at 40 percent or more disabling and the veteran has also suffered service-connected blindness having only light perception or less, or if the veteran has suffered the anatomical loss of both arms with factors that prevent the use of prosthetic appliances, the monthly compensation shall be $4,667;"],[1,"(p) in the event the veteran's service-connected disabilities exceed the requirements for any of the rates prescribed in this section, the Secretary may allow the next higher rate or an intermediate rate, but in no event in excess of $4,667. In the event the veteran has suffered service-connected blindness with 5/200 visual acuity or less and (1) has also suffered bilateral deafness (and the hearing impairment in either one or both ears is service connected) rated at no less than 30 percent disabling, the Secretary shall allow the next higher rate, or (2) has also suffered service-connected total deafness in one ear or service-connected anatomical loss or loss of use of one hand or one foot, the Secretary shall allow the next intermediate rate, but in no event in excess of $4,667. In the event the veteran has suffered service-connected blindness, having only light perception or less, and has also suffered bilateral deafness (and the hearing impairment in either one or both ears is service connected) rated at 10 or 20 percent disabling, the Secretary shall allow the next intermediate rate, but in no event in excess of $4,667. In the event the veteran has suffered the anatomical loss or loss of use, or a combination of anatomical loss and loss of use, of three extremities, the Secretary shall allow the next higher rate or intermediate rate, but in no event in excess of $4,667. Any intermediate rate under this subsection shall be established at the arithmetic mean, rounded down to the nearest dollar, between the two rates concerned."],[1,"[(q) Repealed. Pub. L. 90–493, §4(a), Aug. 19, 1968, 82 Stat. 809.]"],[1,"(r) Subject to section 5503(c) of this title, if any veteran, otherwise entitled to compensation authorized under subsection (o) of this section, at the maximum rate authorized under subsection (p) of this section, or at the intermediate rate authorized between the rates authorized under subsections (n) and (o) of this section and at the rate authorized under subsection (k) of this section, is in need of regular aid and attendance, then, in addition to such compensation—"],[2,"(1) the veteran shall be paid a monthly aid and attendance allowance at the rate of $2,002; or"],[2,"(2) if the veteran, in addition to such need for regular aid and attendance, is in need of a higher level of care, such veteran shall be paid a monthly aid and attendance allowance at the rate of $2,983, in lieu of the allowance authorized in clause (1) of this subsection, if the Secretary finds that the veteran, in the absence of the provision of such care, would require hospitalization, nursing home care, or other residential institutional care."],[1,"For the purposes of clause (2) of this subsection, need for a higher level of care shall be considered to be need for personal health-care services provided on a daily basis in the veteran's home by a person who is licensed to provide such services or who provides such services under the regular supervision of a licensed health-care professional. The existence of the need for such care shall be determined by a physician employed by the Department or, in areas where no such physician is available, by a physician carrying out such function under contract or fee arrangement based on an examination by such physician. For the purposes of section 1134 of this title, such allowance shall be considered as additional compensation payable for disability."],[1,"(s) If the veteran has a service-connected disability rated as total, and (1) has additional service-connected disability or disabilities independently ratable at 60 percent or more, or, (2) by reason of such veteran's service-connected disability or disabilities, is permanently housebound, then the monthly compensation shall be $2,993. For the purpose of this subsection, the requirement of \"permanently housebound\" will be considered to have been met when the veteran is substantially confined to such veteran's house (ward or clinical areas, if institutionalized) or immediate premises due to a service-connected disability or disabilities which it is reasonably certain will remain throughout such veteran's lifetime."],[1,"(t) Subject to section 5503(c) of this title, if any veteran, as the result of service-connected disability, is in need of regular aid and attendance for the residuals of traumatic brain injury, is not eligible for compensation under subsection (r)(2), and in the absence of such regular aid and attendance would require hospitalization, nursing home care, or other residential institutional care, the veteran shall be paid, in addition to any other compensation under this section, a monthly aid and attendance allowance equal to the rate described in subsection (r)(2), which for purposes of section 1134 of this title shall be considered as additional compensation payable for disability. An allowance authorized under this subsection shall be paid in lieu of any allowance authorized by subsection (r)(1)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/1114?type=usc&year=mostrecent&link-type=html"},"by":{"0":"23","1":"40","2":"9"}},{"t":"usc","label":"38 U.S.C. § 5103A","url":"https://www.law.cornell.edu/uscode/text/38/5103A","subs":["(a)(1)"],"stext":{"head":"§5103A. Duty to assist claimants","paras":[[0,"(a) Duty To Assist.—(1) The Secretary shall make reasonable efforts to assist a claimant in obtaining evidence necessary to substantiate the claimant's claim for a benefit under a law administered by the Secretary."],[0,"(2) The Secretary is not required to provide assistance to a claimant under this section if no reasonable possibility exists that such assistance would aid in substantiating the claim."],[0,"(3) The Secretary may defer providing assistance under this section pending the submission by the claimant of essential information missing from the claimant's application."],[0,"(b) Assistance in Obtaining Private Records.—(1) As part of the assistance provided under subsection (a), the Secretary shall make reasonable efforts to obtain relevant private records that the claimant adequately identifies to the Secretary."],[0,"(2)(A) Whenever the Secretary, after making such reasonable efforts, is unable to obtain all of the relevant records sought, the Secretary shall notify the claimant that the Secretary is unable to obtain records with respect to the claim. Such a notification shall—"],[1,"(i) identify the records the Secretary is unable to obtain;"],[1,"(ii) briefly explain the efforts that the Secretary made to obtain such records; and"],[1,"(iii) explain that the Secretary will decide the claim based on the evidence of record but that this section does not prohibit the submission of records at a later date if such submission is otherwise allowed."],[0,"(B) The Secretary shall make not less than two requests to a custodian of a private record in order for an effort to obtain relevant private records to be treated as reasonable under this section, unless it is made evident by the first request that a second request would be futile in obtaining such records."],[0,"(3)(A) This section shall not apply if the evidence of record allows for the Secretary to award the maximum benefit in accordance with this title based on the evidence of record."],[0,"(B) For purposes of this paragraph, the term \"maximum benefit\" means the highest evaluation assignable in accordance with the evidence of record, as long as such evidence is adequate for rating purposes and sufficient to grant the earliest possible effective date in accordance with section 5110 of this title."],[0,"(4) Under regulations prescribed by the Secretary, the Secretary—"],[1,"(A) shall encourage claimants to submit relevant private medical records of the claimant to the Secretary if such submission does not burden the claimant; and"],[1,"(B) in obtaining relevant private records under paragraph (1), may require the claimant to authorize the Secretary to obtain such records if such authorization is required to comply with Federal, State, or local law."],[0,"(c) Obtaining Records for Compensation Claims.—(1) In the case of a claim for disability compensation, the assistance provided by the Secretary under this section shall include obtaining the following records if relevant to the claim:"],[1,"(A) The claimant's service medical records and, if the claimant has furnished the Secretary information sufficient to locate such records, other relevant records pertaining to the claimant's active military, naval, air, or space service that are held or maintained by a governmental entity."],[1,"(B) Records of relevant medical treatment or examination of the claimant at Department health-care facilities or at the expense of the Department, if the claimant furnishes information sufficient to locate those records."],[1,"(C) Any other relevant records held by any Federal department or agency that the claimant adequately identifies and authorizes the Secretary to obtain."],[0,"(2) Whenever the Secretary attempts to obtain records from a Federal department or agency under this subsection, the efforts to obtain those records shall continue until the records are obtained unless it is reasonably certain that such records do not exist or that further efforts to obtain those records would be futile."],[0,"(d) Medical Examinations for Compensation Claims.—(1) In the case of a claim for disability compensation, the assistance provided by the Secretary under subsection (a) shall include providing a medical examination or obtaining a medical opinion when such an examination or opinion is necessary to make a decision on the claim."],[0,"(2) The Secretary shall treat an examination or opinion as being necessary to make a decision on a claim for purposes of paragraph (1) if the evidence of record before the Secretary, taking into consideration all information and lay or medical evidence (including statements of the claimant)—"],[1,"(A) contains competent evidence that the claimant has a current disability, or persistent or recurrent symptoms of disability; and"],[1,"(B) indicates that the disability or symptoms may be associated with the claimant's active military, naval, air, or space service; but"],[1,"(C) does not contain sufficient medical evidence for the Secretary to make a decision on the claim."],[0,"(e) Applicability of Duty to Assist.—(1) The Secretary's duty to assist under this section shall apply only to a claim, or supplemental claim, for a benefit under a law administered by the Secretary until the time that a claimant is provided notice of the agency of original jurisdiction's decision with respect to such claim, or supplemental claim, under section 5104 of this title."],[0,"(2) The Secretary's duty to assist under this section shall not apply to higher-level review by the agency of original jurisdiction, pursuant to section 5104B of this title, or to review on appeal by the Board of Veterans' Appeals."],[0,"(f) Correction of Duty to Assist Errors.—(1) If, during review of the agency of original jurisdiction decision under section 5104B of this title, the higher-level adjudicator identifies or learns of an error on the part of the agency of original jurisdiction to satisfy its duties under this section, and that error occurred prior to the agency of original jurisdiction decision being reviewed, unless the Secretary may award the maximum benefit in accordance with this title based on the evidence of record, the higher-level adjudicator shall return the claim for correction of such error and readjudication."],[0,"(2)(A) If the Board of Veterans' Appeals, during review on appeal of an agency of original jurisdiction decision, identifies or learns of an error on the part of the agency of original jurisdiction to satisfy its duties under this section, and that error occurred prior to the agency of original jurisdiction decision on appeal, unless the Secretary may award the maximum benefit in accordance with this title based on the evidence of record, the Board shall remand the claim to the agency of original jurisdiction for correction of such error and readjudication."],[0,"(B) Remand for correction of such error may include directing the agency of original jurisdiction to obtain an advisory medical opinion under section 5109 of this title."],[0,"(3) Nothing in this subsection shall be construed to imply that the Secretary, during the consideration of a claim, does not have a duty to correct an error described in paragraph (1) or (2) that was erroneously not identified during higher-level review or during review on appeal with respect to the claim."],[0,"(g) Regulations.—The Secretary shall prescribe regulations to carry out this section."],[0,"(h) Rule With Respect to Disallowed Claims.—Nothing in this section shall be construed to require the Secretary to readjudicate a claim that has been disallowed except when new and relevant evidence is presented or secured, as described in section 5108 of this title."],[0,"(i) Other Assistance Not Precluded.—Nothing in this section shall be construed as precluding the Secretary from providing such other assistance under subsection (a) to a claimant in substantiating a claim as the Secretary considers appropriate."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/5103A?type=usc&year=mostrecent&link-type=html"},"by":{"0":"34","1":"40","2":"21, 22"},"q":[{"src":"brief","b":2,"text":"evidence necessary to substantiate the claimant’s claim for a [disability] benefit.","cite":"38 U.S.C. § 5103A(a)(1)"}]},{"t":"usc","label":"38 U.S.C. § 5110","url":"https://www.law.cornell.edu/uscode/text/38/5110","subs":["(a)","(a)(1)","(b)(1)","(b)(3)","(b)(4)","(b)","(b)(4)(A)","(b)(4)(B)","(d)","(i)"],"stext":{"head":"§5110. Effective dates of awards","paras":[[0,"(a)(1) Unless specifically provided otherwise in this chapter, the effective date of an award based on an initial claim, or a supplemental claim, of compensation, dependency and indemnity compensation, or pension, shall be fixed in accordance with the facts found, but shall not be earlier than the date of receipt of application therefor."],[0,"(2) For purposes of determining the effective date of an award under this section, the date of application shall be considered the date of the filing of the initial application for a benefit if the claim is continuously pursued by filing any of the following, either alone or in succession:"],[1,"(A) A request for higher-level review under section 5104B of this title on or before the date that is one year after the date on which the agency of original jurisdiction issues a decision."],[1,"(B) A supplemental claim under section 5108 of this title on or before the date that is one year after the date on which the agency of original jurisdiction issues a decision."],[1,"(C) A notice of disagreement on or before the date that is one year after the date on which the agency of original jurisdiction issues a decision."],[1,"(D) A supplemental claim under section 5108 of this title on or before the date that is one year after the date on which the Board of Veterans' Appeals issues a decision."],[1,"(E) A supplemental claim under section 5108 of this title on or before the date that is one year after the date on which the Court of Appeals for Veterans Claims issues a decision."],[0,"(3) Except as otherwise provided in this section, for supplemental claims received more than one year after the date on which the agency of original jurisdiction issued a decision or the Board of Veterans' Appeals issued a decision, the effective date shall be fixed in accordance with the facts found, but shall not be earlier than the date of receipt of the supplemental claim."],[0,"(b)(1) The effective date of an award of disability compensation to a veteran shall be the day following the date of the veteran's discharge or release if application therefor is received within one year from such date of discharge or release."],[0,"(2)(A) The effective date of an award of disability compensation to a veteran who submits an application therefor that sets forth an original claim that is fully-developed (as determined by the Secretary) as of the date of submittal shall be fixed in accordance with the facts found, but shall not be earlier than the date that is one year before the date of receipt of the application."],[0,"(B) For purposes of this paragraph, an original claim is an initial claim filed by a veteran for disability compensation."],[0,"(C) This paragraph shall take effect on the date that is one year after the date of the enactment of the Honoring America's Veterans and Caring for Camp Lejeune Families Act of 2012 and shall not apply with respect to claims filed after the date that is three years after the date of the enactment of such Act."],[0,"(3) The effective date of an award of increased compensation shall be the earliest date as of which it is ascertainable that an increase in disability had occurred, if application is received within one year from such date."],[0,"(4)(A) The effective date of an award of disability pension to a veteran described in subparagraph (B) of this paragraph shall be the date of application or the date on which the veteran became permanently and totally disabled, if the veteran applies for a retroactive award within one year from such date, whichever is to the advantage of the veteran."],[0,"(B) A veteran referred to in subparagraph (A) of this paragraph is a veteran who is permanently and totally disabled and who is prevented by a disability from applying for disability pension for a period of at least 30 days beginning on the date on which the veteran became permanently and totally disabled."],[0,"(c) The effective date of an award of disability compensation by reason of section 1151 of this title shall be the date such injury or aggravation was suffered if an application therefor is received within one year from such date."],[0,"(d) The effective date of an award of death compensation, dependency and indemnity compensation, or death pension for which application is received within one year from the date of death shall be the first day of the month in which the death occurred."],[0,"(e)(1) Except as provided in paragraph (2) of this subsection, the effective date of an award of dependency and indemnity compensation to a child shall be the first day of the month in which the child's entitlement arose if application therefor is received within one year from such date."],[0,"(2) In the case of a child who is eighteen years of age or over and who immediately before becoming eighteen years of age was counted under section 1311(b) of this title in determining the amount of the dependency and indemnity compensation of a surviving spouse, the effective date of an award of dependency and indemnity compensation to such child shall be the date the child attains the age of eighteen years if application therefor is received within one year from such date."],[0,"(f) An award of additional compensation on account of dependents based on the establishment of a disability rating in the percentage evaluation specified by law for the purpose shall be payable from the effective date of such rating; but only if proof of dependents is received within one year from the date of notification of such rating action."],[0,"(g) Subject to the provisions of section 5101 of this title, where compensation, dependency and indemnity compensation, or pension is awarded or increased pursuant to any Act or administrative issue, the effective date of such award or increase shall be fixed in accordance with the facts found but shall not be earlier than the effective date of the Act or administrative issue. In no event shall such award or increase be retroactive for more than one year from the date of application therefor or the date of administrative determination of entitlement, whichever is earlier."],[0,"(h) Where an award of pension has been deferred or pension has been awarded at a rate based on anticipated income for a year and the claimant later establishes that income for that year was at a rate warranting entitlement or increased entitlement, the effective date of such entitlement or increase shall be fixed in accordance with the facts found if satisfactory evidence is received before the expiration of the next calendar year."],[0,"(i) Whenever any disallowed claim is readjudicated and thereafter allowed on the basis of new and relevant evidence resulting from the correction of the military records of the proper service department under section 1552 of title 10, or the change, correction, or modification of a discharge or dismissal under section 1553 of title 10, or from other corrective action by competent authority, the effective date of commencement of the benefits so awarded shall be the date on which an application was filed for correction of the military record or for the change, modification, or correction of a discharge or dismissal, as the case may be, or the date such disallowed claim was filed, whichever date is the later, but in no event shall such award of benefits be retroactive for more than one year from the date of readjudication of such disallowed claim. This subsection shall not apply to any application or claim for Government life insurance benefits."],[0,"(j) Where a report or a finding of death of any person in the active military, naval, air, or space service has been made by the Secretary concerned, the effective date of an award of death compensation, dependency and indemnity compensation, or death pension, as applicable, shall be the first day of the month fixed by that Secretary as the month of death in such report or finding, if application therefor is received within one year from the date such report or finding has been made; however, such benefits shall not be payable to any person for any period for which such person has received, or was entitled to receive, an allowance, allotment, or service pay of the deceased."],[0,"(k) The effective date of the award of benefits to a surviving spouse or of an award or increase of benefits based on recognition of a child, upon annulment of a marriage shall be the date the judicial decree of annulment becomes final if a claim therefor is filed within one year from the date the judicial decree of annulment becomes final; in all other cases the effective date shall be the date the claim is filed."],[0,"(l) The effective date of an award of benefits to a surviving spouse based upon a termination of a remarriage by death or divorce, or of an award or increase of benefits based on recognition of a child upon termination of the child's marriage by death or divorce, shall be the date of death or the date the judicial decree or divorce becomes final, if an application therefor is received within one year from such termination."],[0,"[(m) Repealed. Pub. L. 103–446, title XII, §1201(i)(8), Nov. 2, 1994, 108 Stat. 4688.]"],[0,"(n) The effective date of the award of any benefit or any increase therein by reason of marriage or the birth or adoption of a child shall be the date of such event if proof of such event is received by the Secretary within one year from the date of the marriage, birth, or adoption."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/5110?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim, 32, passim, passim, 36, 37","1":"3, 21, 3, 21, 3, 21, 3, 21, 3, 21, 3, 21, 3, 21, 3, 21, 3, 21, 3, 21, 3, 21, 3, 21","2":"14, 15, 19, 20, passim, passim, 15"},"q":[{"src":"brief","b":0,"text":"[u]nless specifically provided otherwise in this chapter.","cite":"38 U.S.C. § 5110(a)(1)"},{"src":"brief","b":0,"text":"if application therefor is received within one year from [the veteran’s] date of discharge or release.","cite":"38 U.S.C. § 5110(b)(1)"},{"src":"brief","b":1,"text":"the effective date of an award based on an initial claim * * * of compensation * * * shall be fixed in accordance with the facts found, but shall not be earlier than the date of receipt of application therefor.","cite":"38 U.S.C. 5110(a)(1)"},{"src":"brief","b":1,"text":"effective date * * * shall be the day following the date of the veteran’s discharge or release if application therefor is received within one year from such date of discharge or release.","cite":"38 U.S.C. 5110(b)(1)"},{"src":"argument","who":"Mr. Barney","text":"Now the Secretary attempts to rebut the Irwin presumption by characterizing Section 5110 as a general rule subject to multiple exceptions, but that does not rebut the presumption."},{"src":"argument","who":"Mr. Barney","text":"As I mentioned, there's exceptions rolled in throughout different Congresses and they -- they get codified in Section 5110. The -- the fact that it says specifically, that's a word of emphasis, as this Court has held."}]},{"t":"usc","label":"42 U.S.C. § 2000e-5","url":"https://www.law.cornell.edu/uscode/text/42/2000e-5","subs":["(e)"],"by":{"0":"15"}},{"t":"usc","label":"42 U.S.C. § 6972","url":"https://www.law.cornell.edu/uscode/text/42/6972","subs":["(b)(1)"],"by":{"0":"26"}},{"t":"reg","label":"38 C.F.R. § 3.159","url":"https://www.ecfr.gov/current/title-38/section-3.159","subs":["(c)(4)"],"by":{"0":"34"}},{"t":"reg","label":"38 C.F.R. § 3.326","url":"https://www.ecfr.gov/current/title-38/section-3.326","by":{"0":"34"}},{"t":"case","label":"Artis v. District of Columbia","cite":"138 S. Ct. 594","y":2018,"id":"2017/16-460","sc":1,"by":{"1":"13"}},{"t":"case","label":"Baker Botts L.L.P. v. ASARCO LLC","cite":"576 U.S. 121","y":2015,"id":"2014/14-103","sc":1,"by":{"1":"14"},"q":[{"src":"brief","b":1,"text":"follow the text even if doing so will supposedly ‘undercut a basic objective of the statute,’","cite":"576 U.S. 121, 135"}]},{"t":"case","label":"(III) Cases—Continued: Beach v. Ocwen Federal Bank","cite":"523 U.S. 410","y":1998,"id":"1997/97-5310","sc":1,"by":{"1":"19"},"q":[{"src":"brief","b":1,"text":"govern[s] the life of the underlying right.","cite":"523 U.S. 410, 416-417"}]},{"t":"case","label":"Boechler, P.C. v. Commissioner of Internal Revenue","cite":"142 S. Ct. 1493","y":2022,"id":"2021/20-1472","sc":1,"by":{"1":"16","2":"passim"},"q":[{"src":"brief","b":2,"text":"Equitable tolling is a traditional feature of American jurisprudence and a background principle against which Congress drafts limitations periods.","cite":"142 S. Ct. at 1500"},{"src":"argument","who":"Mr. Joshi","text":"Now it's not always -- as this Court recognized in -- in Boechler in a footnote last year, it's not always an Article III court. It can be a bank -- you know, a bankruptcy court or a tax court, but it's a court of some kind."}]},{"t":"case","label":"California Public Employees’ Retirement System v. ANZ Securities, Inc.","cite":"137 S. Ct. 2042","y":2017,"id":"2016/16-373","sc":1,"by":{"1":"19, 20"},"q":[{"src":"brief","b":1,"text":"designed to encourage plaintiffs ‘to pursue diligent prose- cution of known claims.’","cite":"137 S. Ct. 2042, 2049"}]},{"t":"case","label":"Carlisle v. United States","cite":"517 U.S. 416","y":1996,"id":"1995/94-9247","sc":1,"by":{"1":"29"}},{"t":"case","label":"Chickasaw Nation v. United States","cite":"534 U.S. 84","y":2001,"id":"2001/00-507","sc":1,"by":{"1":"42"}},{"t":"case","label":"City of Arlington v. FCC","cite":"569 U.S. 290","y":2013,"id":"2012/11-1545","sc":1,"by":{"1":"32"}},{"t":"case","label":"Connecticut National Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"by":{"1":"41"},"q":[{"src":"brief","b":1,"text":"canons of construction are no more than rules of thumb that help courts determine the meaning of legislation.","cite":"503 U.S. 249, 253"}]},{"t":"case","label":"EPA v. EME Homer City Generation, L.P.","cite":"572 U.S. 489","y":2014,"id":"2013/12-1182","sc":1,"by":{"1":"14"},"q":[{"src":"brief","b":1,"text":"a reviewing court’s ‘task is to apply the text of the statute, not to improve upon it,’","cite":"572 U.S. 489, 508-509"}]},{"t":"case","label":"Erspamer v. Brown","cite":"9 Vet. App. 507","y":1996,"url":"https://www.courtlistener.com/c/Vet.%20App./9/507/","by":{"1":"34"}},{"t":"case","label":"Hamdan v. Rumsfeld","cite":"548 U.S. 557","y":2006,"id":"2005/05-184","sc":1,"by":{"1":"32"}},{"t":"case","label":"Heimeshoff v. Hartford Life & Accident Insurance Co.","cite":"571 U.S. 99","y":2013,"id":"2013/12-729","sc":1,"by":{"1":"18"}},{"t":"case","label":"Holland v. Florida","cite":"560 U.S. 631","y":2010,"id":"2009/09-5327","sc":1,"by":{"1":"16, 39","2":"17, 24"}},{"t":"case","label":"King v. St. Vincent’s Hospital","cite":"502 U.S. 215","y":1991,"id":"1991/90-889","sc":1,"by":{"1":"42"}},{"t":"case","label":"Maggitt v. West","cite":"202 F.3d 1370","y":2000,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/202/1370/","by":{"1":"40"},"q":[{"src":"brief","b":1,"text":"the existence of disability, * * * the degree of the disability, and the effective date of the disability.","cite":"202 F.3d 1370, 1375"}]},{"t":"case","label":"Office of Personnel Management v. Richmond","cite":"496 U.S. 414","y":1990,"id":"1989/88-1943","sc":1,"by":{"1":"36"}},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"by":{"1":"45","2":"23, 24"},"q":[{"src":"brief","b":1,"text":"[t]hat is particularly true where * * * ‘Congress has enacted a comprehensive scheme and has deliberately targeted specific problems with specific solutions.’","cite":"566 U.S. 639, 645"}]},{"t":"case","label":"Rotkiske v. Klemm","cite":"140 S. Ct. 355","y":2019,"id":"2019/18-328","sc":1,"by":{"1":"32","2":"16"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"by":{"1":"34"}},{"t":"case","label":"Shapiro v. McManus","cite":"577 U.S. 39","y":2015,"id":"2015/14-990","sc":1,"by":{"1":"28"},"q":[{"src":"brief","b":1,"text":"the mandatory ‘shall’ normally creates an obligation impervious to judicial discretion.","cite":"577 U.S. 39, 43"}]},{"t":"case","label":"Titone v. McDonald","cite":"637 Fed. Appx. 592","y":2016,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./637/592/","by":{"1":"36"}},{"t":"case","label":"United States v. Dalm","cite":"494 U.S. 596","y":1990,"id":"1989/88-1951","sc":1,"by":{"1":"31"},"q":[{"src":"brief","b":1,"text":"would be doing little more than overriding Congress’ judgment as to when equity requires that there be an exception to the","cite":"494 U.S. 596, 610"}]},{"t":"case","label":"United States v. Robinson","cite":"361 U.S. 220","y":1960,"id":"1959/16","sc":1,"by":{"1":"29"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","by":{"1":"15, 17"}},{"t":"usc","label":"28 U.S.C. § 2412","url":"https://www.law.cornell.edu/uscode/text/28/2412","by":{"1":"17"}},{"t":"law","label":"Pub. L. No. 85-56","url":"https://www.govinfo.gov/link/statute/71/119","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 106-419","url":"https://www.govinfo.gov/link/plaw/106/public/419","by":{"1":"34"}},{"t":"law","label":"Veterans’ Judicial Review Act, Pub. L. No. 100-687","url":"https://www.govinfo.gov/link/statute/102/4105","by":{"1":"33"}},{"t":"usc","label":"17 U.S.C. § 507","url":"https://www.law.cornell.edu/uscode/text/17/507","subs":["(b)"],"stext":{"head":"§507. Limitations on actions","paras":[[0,"(a) Criminal Proceedings.—Except as expressly provided otherwise in this title, no criminal proceeding shall be maintained under the provisions of this title unless it is commenced within 5 years after the cause of action arose."],[0,"(b) Civil Actions.—No civil action shall be maintained under the provisions of this title unless it is commenced within three years after the claim accrued."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/17/507?type=usc&year=mostrecent&link-type=html"},"by":{"1":"25","2":"10"},"q":[{"src":"brief","b":1,"text":"within three years after the claim accrued","cite":"17 U.S.C. 507(b)"}]},{"t":"usc","label":"35 U.S.C. § 286","url":"https://www.law.cornell.edu/uscode/text/35/286","by":{"1":"25","2":"10"}},{"t":"usc","label":"38 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/38/101","subs":["(16)"],"by":{"1":"2"}},{"t":"usc","label":"38 U.S.C. § 1110","url":"https://www.law.cornell.edu/uscode/text/38/1110","by":{"1":"2, 20"}},{"t":"usc","label":"38 U.S.C. § 1131","url":"https://www.law.cornell.edu/uscode/text/38/1131","by":{"1":"2, 20, 32"},"q":[{"src":"brief","b":1,"text":"aggravation of a preexisting injury suffered or disease contracted in line of duty.","cite":"38 U.S.C. 1131"}]},{"t":"usc","label":"38 U.S.C. § 1521","url":"https://www.law.cornell.edu/uscode/text/38/1521","by":{"1":"32"}},{"t":"usc","label":"38 U.S.C. § 5101","url":"https://www.law.cornell.edu/uscode/text/38/5101","subs":["(a)(1)(A)"],"by":{"1":"24"}},{"t":"usc","label":"38 U.S.C. § 5108","url":"https://www.law.cornell.edu/uscode/text/38/5108","by":{"1":"21"}},{"t":"usc","label":"38 U.S.C. § 5111","url":"https://www.law.cornell.edu/uscode/text/38/5111","subs":["(a)(1)"],"by":{"1":"3, 21"}},{"t":"usc","label":"38 U.S.C. § 5113","url":"https://www.law.cornell.edu/uscode/text/38/5113","subs":["(a)","(b)","(b)(1)","(b)(2)(A)"],"by":{"1":"34, 34, 11, 34, 34","2":"19, 19, 19"},"q":[{"src":"brief","b":2,"text":"[t]he obvious inference from the absence of comparable language in Section 5110 is that respondent possesses no such authority with respect to service-connected disability compensation.","cite":"38 U.S.C. § 5113(b)(1)"}]},{"t":"reg","label":"38 C.F.R.: Section 3.400(b)(2) .......................................................... 4, 8a Section 3.400(b)(2)(i)......................, 26 Fed. Reg. 1561","url":"https://www.govinfo.gov/link/fr/26/1561","by":{"1":"4"}},{"t":"case","label":"Aspen Tech., Inc. v. M3 Tech., Inc.","cite":"569 F. App’x 259","y":2014,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/569/259/","by":{"2":"10"}},{"t":"case","label":"Bailey v. Glover","cite":"88 U.S. 342","y":1874,"id":"scdb/1874-150","sc":1,"by":{"2":"22"}},{"t":"case","label":"Baldwin Cnty. Welcome Ctr. v. Brown","cite":"466 U.S. 147","y":1984,"id":"1983/83-181","sc":1,"by":{"2":"22"}},{"t":"case","label":"Barrett v. Principi","cite":"363 F.3d 1316","y":2004,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/363/1316/","by":{"2":"13"}},{"t":"case","label":"Meyer v. Holley","cite":"537 U.S. 280","y":2003,"id":"2002/01-1120","sc":1,"by":{"2":"16, 20"}},{"t":"case","label":"PDR Network, LLC v. Carlton & Harris Chiropractic, Inc.","cite":"139 S. Ct. 2051","y":2019,"id":"2018/17-1705","sc":1,"by":{"2":"21"}},{"t":"case","label":"United States v. Kubrick","cite":"444 U.S. 111","y":1979,"id":"1979/78-1014","sc":1,"by":{"2":"6, 8"}},{"t":"usc","label":"28 U.S.C. § 6511","url":"https://www.law.cornell.edu/uscode/text/28/6511","by":{"2":"17"}},{"t":"usc","label":"38 U.S.C. § 501","url":"https://www.law.cornell.edu/uscode/text/38/501","subs":["(a)"],"by":{"2":"18"},"q":[{"src":"brief","b":2,"text":"authority to prescribe all rules and regulations which are necessary or appropriate to carry out the laws administered by the Department.","cite":"38 U.S.C. § 501(a)"}]},{"t":"usc","label":"38 U.S.C. § 7292","url":"https://www.law.cornell.edu/uscode/text/38/7292","subs":["(c)"],"by":{"2":"13"}},{"t":"law","label":"Pub. L. No. 85-857","url":"https://www.govinfo.gov/link/statute/72/1105","by":{"2":"20"}},{"t":"reg","label":"38 C.F.R. § 3.109","url":"https://www.ecfr.gov/current/title-38/section-3.109","subs":["(b)"],"by":{"2":"18"},"q":[{"src":"brief","b":2,"text":"[t]ime limit[] within which claimants or beneficiaries are required to act to perfect a claim or challenge an adverse VA decision.","cite":"38 C.F.R. § 3.109(b)"}]}]};